"""Curated first release. The editable source of truth is data/papers/*.json.
This migration is kept for provenance; do not rerun after editing records manually.
"""
import json,re,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1]
exec((R/'scripts/ingest.py').read_text().split('for row in table(')[0])
items={p.stem:json.loads(p.read_text()) for p in (R/'data/papers').glob('*.json')}
deleted=[]
def src(url,label,loc='',supports=None):return dict(kind='primary',url=url,label=label,locator=loc,supports=supports or ['身份','核心方法'])
def put(id,title,short,match=(),**kw):
 p=base(title,short);p['id']=id;p['status']='重点详解';p['checked']='2026-10-19';p['gaps']=['尚未逐项核实所有资源许可证与下载内容']
 p['verification']='已核验核心信息；缺失字段继续标为未核实'
 for k,v in list(items.items()):
  if norm(v['title']) in [norm(x) for x in [title,short,*match]]:
   p['sources']+=v['sources'];p['sourceNotes']+=v['sourceNotes'];p['aliases']+=v['aliases']+[v['title']];del items[k];deleted.append([k,id])
 for key,value in kw.items():
  if key=='tags':
   for d,ts in value.items():p['tags'][d]=ts.split('|')
  else:p[key]=value
 if p['firstPublished']:p['year']=int(p['firstPublished'][:4])
 items[id]=p;return p
def method(inp,out,flow,assumptions,difference):return dict(input=inp,output=out,flow=flow,assumptions=assumptions,difference=difference)
def train(regime,models,trainable,frozen,data,objective,stages):return dict(regime=regime,models=models,trainable=trainable,frozen=frozen,data=data,objective=objective,stages=stages)
def ev(bench,setting,result,loc=''):return dict(benchmark=bench,setting=setting,result=result,locator=loc,attribution='作者报告')
def lim(author,analysis):return dict(author=author,analysis=analysis)
def res(**kw):return {k:dict(url=v,status='已核实入口') for k,v in kw.items()}
put('4dgs-deformation','4D Gaussian Splatting for Real-Time Dynamic Scene Rendering','4D-GS · 形变场',firstPublished='2023-10-12',updated='2024-07-15',venue='CVPR',publicationYear=2024,publicationStatus='已发表',authors=['Guanjun Wu','Taoran Yi','Jiemin Fang','Lingxi Xie','Xiaopeng Zhang','Wei Wei','Wenyu Liu','Qi Tian','Xinggang Wang'],institutions=['华中科技大学','华为'],tags=dict(direction='场景表征',task='动态重建',paradigm='3D/4D 表征',system='场景表示',contribution='方法',problem='动态环境|实时性',environment='离线重建',training='场景表示优化'),summary='把动态场景表示为一组规范空间 3D 高斯与时间条件形变：HexPlane 风格特征和轻量 MLP 预测每个时刻的高斯变化，避免逐帧独立建模。它学习的是“高斯怎样变化”，与原生四维高斯路线不同。',overview='动态重建需要同时描述外观、几何与运动。4D-GS 保留可快速渲染的 3D 高斯，并用分解时空特征编码与轻量网络预测形变，从不同时间的图像共同优化一个场景。理解它时，应把规范空间、时空特征和渲染分开看：这是一种逐场景拟合的方法，实时渲染不代表能在机器人采集时实时完成重建。',method=method('带时间与相机参数的图像序列','任意已建模时间和新视角的 RGB 渲染',['建立规范空间 3D 高斯','查询分解时空特征','MLP 预测高斯形变','可微投影与图像重建优化'],'需要相机标定及足够观测；依赖具体数据预处理','时间通过特征与形变网络进入；不直接优化一个原生 4D 协方差作为全部运动表示。'),training=train('场景表示优化','3D 高斯、时空特征编码、轻量 MLP','场景高斯、时空特征和形变参数','不适用：不是 VLM 微调','目标场景视频/多视角图像','图像重建及时空正则；具体权重请查代码配置','逐场景优化 → 渲染'),evaluation=[ev('动态新视角合成','原论文指定数据与相机协议','比较重建质量、渲染速度和存储；本库未导入跨论文统一速度榜。')],limitations=lim([],['优化结果不自动提供 watertight Mesh、碰撞体或可交互物理状态；导航环境需另建几何与事件接口。']),resources=res(paper='https://arxiv.org/abs/2310.08528',project='https://guanjunwu.github.io/4dgs/'),sources=[src('https://arxiv.org/abs/2310.08528','arXiv v3','摘要、版本历史',['身份','日期','方法']),src('https://guanjunwu.github.io/4dgs/','官方项目页','方法与发表信息',['发表','方法','代码入口'])],related=[dict(id='4dgs-native',reason='相同动态渲染目标，不同时间表示'),dict(id='shape-of-motion',reason='比较显式长程运动轨迹')])
put('4dgs-native','Real-time Photorealistic Dynamic Scene Representation and Rendering with 4D Gaussian Splatting','4DGS · 原生四维',firstPublished='2023-10-16',updated='2024-02-22',venue='ICLR',publicationYear=2024,publicationStatus='已发表',authors=['Zeyu Yang','Hongye Yang','Zijie Pan','Li Zhang'],institutions=['复旦大学'],tags=dict(direction='场景表征',task='动态重建',paradigm='3D/4D 表征',system='场景表示',contribution='方法',problem='动态环境|实时性',environment='离线重建',training='场景表示优化'),summary='直接优化联合空间与时间的四维高斯，以时空协方差刻画运动关联，在指定时刻得到用于投影的空间分布；无需先把所有动态写成规范空间形变网络。',overview='这篇 ICLR 2024 工作把时间与三维空间一起纳入高斯基元。直观上，一个倾斜穿过时间轴的四维高斯，可以在不同时刻产生位于不同空间位置的切片。模型同时拟合几何与外观，目标是动态新视角合成。它适合用来理解“直接表示时空”与“先建立静态参考再预测形变”的差别；两篇工作不能只按 4DGS 简称合并。',method=method('带相机参数及时间戳的动态图像','指定视角和时刻的渲染',['优化四维高斯均值与时空协方差','在查询时刻条件化空间分布','计算时间相关权重与外观','投影并融合空间高斯'],'四维分布的可拟合范围仍受视频观测覆盖限制','运动关联直接进入时空分布；不是 HexPlane 加形变 MLP。'),training=train('场景表示优化','4D 高斯及时间相关外观基','四维几何、透明度及外观参数','不适用：没有 VLM 主干','目标场景图像','可微渲染的图像重建','逐场景拟合 → 时间条件渲染'),evaluation=[ev('单目与多视角动态场景','原文的新视角/时间评测','作者比较画质与效率；不在此混合不同硬件的 FPS。')],limitations=lim([],['时空高斯不等同于显式物体动力学；不能仅凭可渲染性推断 Mesh 可碰撞、事件可重置或未观测未来可预测。']),resources=res(paper='https://arxiv.org/abs/2310.10642',project='https://fudan-zvg.github.io/4d-gaussian-splatting/'),sources=[src('https://arxiv.org/abs/2310.10642','arXiv v3','摘要、版本历史',['日期','身份','方法']),src('https://fudan-zvg.github.io/4d-gaussian-splatting/','官方项目页','ICLR 版与扩展版分别提供链接',['发表','版本关系','方法'])],related=[dict(id='4dgs-deformation',reason='两种不同的时间建模路线')])
put('shape-of-motion','Shape of Motion: 4D Reconstruction from a Single Video','Shape of Motion',firstPublished='2024-07-18',venue='ICCV',publicationYear=2025,publicationStatus='已发表',authors=['Qianqian Wang','Vickie Ye','Hang Gao','Weijia Zeng','Jake Austin','Zhengqi Li','Angjoo Kanazawa'],institutions=['UC Berkeley','Google Research','UC San Diego'],tags=dict(direction='场景表征',task='动态重建|跟踪',paradigm='3D/4D 表征',system='场景表示',contribution='方法',problem='动态环境|空间理解',environment='真实世界|离线重建',training='场景表示优化'),summary='用少量共享 SE(3) 运动基描述持久 3D 高斯的全视频运动，结合单目深度与长程 2D 跟踪先验，联合恢复几何、轨迹与外观。',overview='普通单视频无法直接观察同一时刻的所有侧面，动态重建因而高度欠约束。Shape of Motion 用共享运动基减少运动自由度，并融合有噪声的深度和二维跟踪约束，得到跨整段视频的持久三维轨迹。它同时关注跟踪与新视角渲染。对真实采集项目，先检查位姿、掩码、深度与跟踪预处理，再判断已有 LiDAR 能替代哪些估计量；原仓库不是直接读取机器人 MCAP 的现成管线。',method=method('视频帧、相机内外参与估计深度/二维轨迹','持久三维运动轨迹与动态高斯渲染',['估计/准备相机、深度与长程跟踪','建立共享 SE(3) 运动基','给高斯分配运动基组合权重','联合优化几何、运动与外观'],'依赖输入先验质量和动态区域的可观测性','显式恢复整段轨迹，而非只预测相邻帧 scene flow。'),training=train('场景表示优化','预训练深度与跟踪工具；动态高斯表示','每段场景的运动基、权重、几何和外观','前处理基础模型作为先验；未声称训练 VLM','单视频及其估计先验','图像、深度与跟踪的一致性优化','前处理 → 场景拟合 → 留出视角/轨迹评估'),evaluation=[ev('动态视频重建与跟踪','真实及合成动态视频','原文分别评测长程 2D/3D 运动估计与新视角合成。')],limitations=lim([],['单视频缺失视角没有独立测量；补拍终态不能充当历史动态时刻的另一视角真值。']),resources=res(paper='https://arxiv.org/abs/2407.13764',project='https://shape-of-motion.github.io/',code='https://github.com/vye16/shape-of-motion'),sources=[src('https://shape-of-motion.github.io/','官方项目页','方法与作者',['作者','发表','方法']),src('https://github.com/vye16/shape-of-motion','官方代码','预处理与自采数据入口',['资源','输入']),src('https://openaccess.thecvf.com/content/ICCV2025/html/Wang_Shape_of_Motion_4D_Reconstruction_from_a_Single_Video_ICCV_2025_paper.html','ICCV 2025 论文集','论文身份与摘要',['发表','作者','方法'])],related=[dict(id='4dgs-native',reason='比较原生时空分布与显式轨迹')])
put('openvla','OpenVLA: An Open-Source Vision-Language-Action Model','OpenVLA',firstPublished='2024-06-13',updated='2024-09-05',publicationStatus='预印本（正式发表状态未核实）',authors=['Moo Jin Kim','Karl Pertsch','Siddharth Karamcheti','Ted Xiao','Ashwin Balakrishna','Suraj Nair','Rafael Rafailov','Ethan Foster','Grace Lam','Pannag Sanketi','Quan Vuong','Thomas Kollar','Benjamin Burchfiel','Russ Tedrake','Dorsa Sadigh','Sergey Levine','Percy Liang','Chelsea Finn'],tags=dict(direction='操作',task='抓取|机器人控制',paradigm='VLA|模仿学习',system='端到端策略',contribution='方法|模型',problem='泛化',environment='真实世界|机械臂',training='监督微调'),summary='以 Prismatic VLM 为基础，用真实机器人示范学习离散动作 token，提供开放的 7B VLA 权重与下游微调流程。',overview='OpenVLA 把机器人动作转换为可预测 token，让图像、语言与动作学习共享一个模型。视觉侧融合 DINOv2 与 SigLIP，语言侧使用 Llama 2 7B，并在机器人示范上训练。它的价值既包括可下载策略，也包括把通用 VLA 适配到新机器人与任务的工程路径。使用时需分别理解通用预训练与自己任务上的微调，不能因为使用预训练权重就把完整系统称为“无训练”。',method=method('RGB 观测与自然语言指令','离散化的末端动作 token',['融合视觉特征','投影为语言模型 token','自回归预测动作','反量化并执行'],'需匹配动作归一化、机器人构型与控制频率','开放权重与微调方案支持下游适配。'),training=train('监督微调','Prismatic；DINOv2 + SigLIP；Llama 2 7B','通用 VLA 训练及下游适配参数；LoRA 为一种下游选项','不同微调配置有差异，需按所用脚本确认','Open X-Embodiment 中约 970k 真实机器人轨迹','动作 token 预测','VLM 初始化 → 机器人训练 → 下游微调'),evaluation=[ev('通用操作及下游适配','跨任务、物体与机器人平台；各实验协议不同','作者报告通用策略与下游微调实验，不合并成统一成功率。')],limitations=lim([],['部署仍需机器人接口、动作归一化与安全控制；开放模型不消除数据分布和控制频率差异。']),resources=res(paper='https://arxiv.org/abs/2406.09246',project='https://openvla.github.io/',code='https://github.com/openvla/openvla',weights='https://huggingface.co/openvla/openvla-7b'),sources=[src('https://arxiv.org/abs/2406.09246','arXiv v3','摘要、历史',['作者','日期','规模']),src('https://openvla.github.io/','官方项目页','模型、训练、适配',['方法','训练','资源'])])
