p=put('openeqa','OpenEQA: Embodied Question Answering in the Era of Foundation Models','OpenEQA',venue='CVPR',publicationYear=2024,publicationStatus='已发表',institutions=['Meta FAIR'],tags=dict(direction='导航|综合具身智能',task='EQA',paradigm='VLM',system='评测平台',contribution='Benchmark|数据集',problem='记忆|空间理解',environment='仿真|室内|真实采集资产',training='不适用'),summary='用开放式自然语言问题评估环境理解，区分读取历史的 EM-EQA 与允许行动的 A-EQA；二者共享问题来源但输入权限和评测协议不同。',overview='OpenEQA 问的是机器人是否真正理解所见环境，而不只是能否定位一个物体。它提供人类编写的开放式问答和自动评测，将基于既有观察历史的问答，与需要主动探索获取证据的问答分开。读实验时必须检查是 EM-EQA 还是 A-EQA、题目子集与探索预算，不能把各论文使用不同设置的 LLM-Match 分数直接拼成排行榜。',method=method('问题＋历史观测，或问题＋可行动环境','开放式自然语言答案',['选择 EM 或 Active 协议','提供观测历史或允许探索','产生回答','按自动评测与参考答案评分'],'场景资产与历史数据受各自获取条件约束','开放式问答，区别于封闭选项准确率。'),training=train('不适用','Benchmark 评估多个预训练模型','不适用：基准本身不是一个训练策略','各被测方法分别声明','1600+ 人工问答，180+ 环境','不适用','数据采集/问答 → 基线评测'),evaluation=[ev('OpenEQA','EM 与 Active 两种设置','官方提供 LLM 自动评分；原始实验显示模型与人类仍有明显差距。')],limitations=lim([],['LLM judge 的版本和提示会影响可比性；图像历史问答不能独立证明实时行动能力。']),resources=res(project='https://open-eqa.github.io/',code='https://github.com/facebookresearch/open-eqa',data='https://github.com/facebookresearch/open-eqa'),sources=[src('https://open-eqa.github.io/','官方项目页','任务、作者、BibTeX',['任务','发表','规模']),src('https://github.com/facebookresearch/open-eqa','官方仓库','Dataset、Baselines、Evaluation、License',['协议','资源','许可证'])])
