p=put('goat-bench','GOAT-Bench: A Benchmark for Multi-Modal Lifelong Navigation','GOAT-Bench',firstPublished='2024-04-09',publicationStatus='预印本（正式发表状态未核实）',authors=['Mukul Khanna','Ram Ramrakhya','Gunjan Chhablani','Sriram Yenamandra','Theophile Gervet','Matthew Chang','Zsolt Kira','Devendra Singh Chaplot','Dhruv Batra','Roozbeh Mottaghi'],tags=dict(direction='导航',task='ObjectNav|ImageNav|多目标导航',paradigm='强化学习',system='评测平台',contribution='Benchmark|数据集',problem='记忆|泛化',environment='仿真|室内|真实采集资产',training='不适用'),summary='在一次 episode 内顺序寻找 5–10 个目标，目标可用类别、语言描述或图像指定，测试多模态目标理解与跨子任务记忆。',overview='单目标导航通常在找到目标后重置环境，难以检验观察历史能否帮助后续任务。GOAT-Bench 将类别、语言与图像目标放入同一个多目标序列，保留场景经历，比较模块化地图系统与端到端 RL。这里的 lifelong 指跨子任务持续使用经验，并不自动表示环境中的物体随时间移动，也不代表测试期间更新模型权重。',method=method('当前传感器与顺序多模态目标','导航动作及子任务完成信号',['读取当前目标模态','在场景中行动','完成或结束当前子任务','保留或消融记忆后处理下一目标'],'依赖 HM3D 资产与官方 episode 资源','同时检验目标模态统一和多目标记忆。'),training=train('不适用','模块化与 SenseAct-NN RL 基线','不同基线分别训练或使用预训练模块','不适用','官方任务 episode','按各基线定义','Benchmark 构造 → 基线训练/评估'),evaluation=[ev('GOAT','类别、语言、图像目标分别统计','分别分析 SR/SPL、记忆消融与目标描述噪声。')],limitations=lim([],['真实扫描外观与实机控制是不同维度；顺序目标任务不能替代真实动态目标搬移评测。']),resources=res(paper='https://arxiv.org/abs/2404.06609',project='https://mukulkhanna.github.io/goat-bench/',code='https://github.com/Ram81/goat-bench',data='https://github.com/Ram81/goat-bench'),sources=[src('https://arxiv.org/abs/2404.06609','arXiv','日期与作者',['日期','作者']),src('https://mukulkhanna.github.io/goat-bench/','官方项目页','任务与基线',['任务','评测']),src('https://github.com/Ram81/goat-bench/blob/main/README.md','官方仓库','下载与任务说明',['资源','协议'])])
