p=items['realtwin'];p.update(authors=['Jiaxuan Liu','Yunkang Cao','Yufeng Chen','Chunyang Li','Yuhuan Du','Hui Zhang'],summary='将真实相机视图与同位姿 CAD 渲染参照配对，通过轻量对齐模块和正常样本学习检测异常，主干视觉模型冻结。',overview='真实工业图像与 CAD 参照有材质、光照和成像差异，直接相减难以定位缺陷。该工作构建同位姿 Real-to-Twin 对，使用冻结视觉特征和可训练对齐模块减少域差异，再从匹配后的特征差异判断异常。“Zero-shot”指类别隔离的测试协议，不代表整套方法没有训练：对齐模块仍使用正常训练对优化。',method=method('实拍图像、CAD 及对应相机/物体位姿','异常图与异常评分',['采集/渲染同位姿图像对','冻结 DINOv2 编码','跨域特征对齐与重组','计算异常差异'],'需要 CAD 与可靠位姿/标定','以可匹配数字参照替代无条件通用视觉判别。'),training=train('冻结主干并训练模块','DINOv2 ViT-S/14','轻量投影与对齐模块','DINOv2 视觉主干','216 对正常 flange-bearing seat 训练样本；214 对新类别 J6 测试','局部/全局一致性','50 epochs；只用正常训练对优化'),evaluation=[ev('Real-to-Twin 配对数据','216正常训练对，214新类别测试对，类别不重叠','异常检测/分割及跨类别零样本协议；未导入未经复核的性能数字。','实验设置')],limitations=lim([],['强 CAD/位姿前提限制无模型家庭物体；类别隔离不消除 CAD 或相机设置层面的偏差。']));p['tags'].update(direction=['操作'],environment=['真实世界','机械臂'],training=['冻结主干并训练模块'],contribution=['方法','数据集'],problem=['主动感知','泛化'])
p=items['inspection-vla'];p.update(authors=['Martin Krüger','Mahmoud Salem','Markus Reischl'],institutions=['Karlsruhe Institute of Technology'],venue='Neural Processing Letters',publicationYear=2026,publicationStatus='已发表',summary='将操作预训练 OpenVLA 微调用于二维特征跟随巡检，比较单视图和双相机融合，并用动作级与轨迹级指标评估。',overview='巡检常要求传感器沿着某条特征移动，同时不改变被检查物。论文用桌面二维特征跟随任务检验操作预训练 VLA 能否适配这种运动目标，提出训练时动作级评价与完整轨迹对齐评价。研究给出了真实机器人可行性证据，但场景、任务与人类基线规模有限，不能由此推断复杂三维设备巡检已经解决。',method=method('相机图像与巡检指令','末端运动增量',['半自动采集特征跟随示范','构建单/双相机输入','微调 OpenVLA','机器人 rollout 与轨迹评价'],'二维任务和受控硬件设置','把操作预训练 VLA 迁移到不改变对象的传感器运动。'),training=train('监督微调','OpenVLA','面向特征跟随的适配参数；具体冻结层待核实','未核实','100训练轨迹、10验证轨迹','动作学习与动作级评价早停','示范 → 微调 → 新形状 rollout'),evaluation=[ev('自建二维跟随任务','真实机器人、单个操作者基线','比较 DDTW 轨迹对齐与位置误差；结果限于受控任务。','§2.4 与结果')],limitations=lim(['研究规模有限；人类 Benchmark 基于单个操作者。'],['二维特征跟随不包含自由导航、设备诊断和多轮故障演化。']),resources=res(paper='https://doi.org/10.1007/s11063-026-11860-3'));p['tags'].update(direction=['操作'],paradigm=['VLA','模仿学习'],environment=['真实世界','机械臂'],training=['监督微调'])
p=items['hros'];p.update(authors=['Yaoyuan Yan','Zhiyou Heng','Haoxiang Jie','Gang Liu','Hongjie Yan','Wei Zhou'],summary='把四足巡检的导航、感知、交互与企业告警串成可追踪闭环，用运行时管理上下文、能力与受控更新。',overview='论文强调巡检部署的系统集成问题：单独具备导航和异常识别能力，不代表能在长时任务中维护状态、复用经验并产生可追踪报告。HROS 将底层自治栈与上层多模态推理、交互和任务运行时相接，展示物业环境部署。系统功能声明、已执行现场实验和未来能力需要分开阅读，尤其不能把提出更新机制写成已验证长期自进化。',method=method('语音/文字任务、机器人传感器、执行状态','巡检动作、异常报告及告警',['接收任务并建立上下文','调用导航和巡检能力','记录多模态反馈','生成报告并处理更新'],'依赖导航定位栈、接口和部署网络','关注完整运行时与企业工作流。'),training=train('训练细节未公开/未核实','Qwen3-VL 与机器人导航组件','各组件是否专门训练需按模块核实','不能仅凭调用 VLM 推断全系统无训练','部署数据与受控实验','未核实','组件集成 → 现场与受控评估'),evaluation=[ev('物业四足巡检部署','导航、定位、识别、告警与受控认知运行时实验','本库不把不同子系统指标汇成统一任务成功率。','§5–§8')],limitations=lim(['需要长期地图维护、更广泛开放世界隐患数据。'],['现场功能演示不能替代标准 Agent Benchmark 或跨天重复任务对照。']));p['tags'].update(direction=['导航'],system=['具身 Agent'],environment=['真实世界','四足机器人'],contribution=['系统'],training=['训练细节未公开'],problem=['记忆','安全'])
