p=items['semantic-inspection'];p.update(authors=['Grzegorz Malczyk','Mihir Kulkarni','Kostas Alexis'],venue='IEEE Robotics and Automation Letters',publicationYear=2025,publicationStatus='已录用（所附 PDF 明示）',summary='用语义感知深度强化学习联合规划目标物体检查与无碰撞导航；不是语言 VLM 微调方法。',overview='在未知环境中，并非每个表面都同等重要。论文让巡检策略依据目标语义、深度、局部占用与过去位置，选择能观察感兴趣对象的运动。研究价值在于把检查覆盖与导航约束放入同一个学习策略。它不应被归入“无训练 VLM”：系统没有使用语言 VLM，但确实训练了强化学习策略。',method=method('深度、分割、局部占用与历史位置','巡检导航动作',['编码局部观测与历史','估计语义检查价值','RL 策略选择动作','在避障约束下继续检查'],'需要可靠分割与局部几何','目标语义驱动检查，而非均匀覆盖。'),training=train('强化学习','深度 RL 策略；无语言 VLM','导航与检查策略','不适用','仿真巡检环境','检查收益与导航安全相关奖励','仿真训练 → 巡检评测'),evaluation=[ev('语义巡检任务','详见所附原文实验','本次核实方法和训练类型，未抄录未经逐表检查的数字。')],limitations=lim([],['没有语言 VLM 不等于系统完全无训练；设备根因诊断与长期演化不属于核心目标。']));p['tags'].update(direction=['导航'],paradigm=['强化学习'],training=['强化学习'],problem=['主动感知'])
p=items['ccv-vlm'];p.update(authors=['Huanyu Wang','Futian Guo','Qihao Wang','Jiajing Liu'],venue='Advanced Engineering Informatics',publicationYear=2026,publicationStatus='已发表（所附 PDF）',summary='用多模型协同交叉验证处理施工安全视觉检查，作为具身巡检中的可靠视觉判别相关工作。',overview='施工安全图像包含专业术语与复杂背景，通用 VLM 可能输出不稳定判断。该工作通过协同交叉验证组织视觉推理，目标是提高多任务检查可靠性。收录它是为了提供安全视觉判断的技术背景，而不把单张图像上的检查效果视为机器人已经具备自主移动、取证和处置能力。',method=method('施工安全图像与检查问题','安全判断及解释',['多个视觉推理分支','交叉检查候选判断','汇总一致性结论'],'专业类别与图像分布影响结论','通过交叉验证改善视觉判断。'),training=train('训练细节未公开/未核实','协同 VLM 组件','未核实','未核实','施工安全视觉数据；规模待核实','未核实','详见所附原文'),evaluation=[ev('施工安全视觉检查','图像任务；非实机导航','数据划分、量化结果尚待逐表复核。')],limitations=lim([],['没有实机动作反馈，不能直接评估主动巡检成本。']));p['tags'].update(environment=['静态图像'],training=['训练细节未公开']);p['gaps']+=['训练冻结配置','数据划分与逐表量化复核','论文 DOI 与资源入口']

